 END IF;
 IF NOT EXISTS(SELECT 1 FROM "VerificationMedia" m JOIN "Users" u ON u."UserId"=m."OwnerId"
  WHERE m."Id"=media_id AND m."OwnerId"=owner_id AND m."Purpose"='financial-momo-receive-qr'
